export interface HubSpotDealWebhookPayload {
  dealId: number;
  properties: {
    dealname: string;
    amount: number;
    associatedcompanyid: number;
    domain?: string;
  };
  objectId: number;
  subscriptionId: string;
  propertyName: string;
  propertyValue: string;
  changeSource: string;
}

export interface ConnectorConfig {
  fetch: typeof fetch;
  salesforceInstanceUrl: string;
  salesforceAccessToken: string;
  hubspotAccessToken: string;
  hubspotBaseUrl?: string;
  resolveCompanyDomain?: (companyId: number) => Promise<string>;
}

export interface UpsertResult {
  id: string;
  success: boolean;
  errors: string[];
  created: boolean;
}

export async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig
): Promise<UpsertResult> {
  if (!payload.properties?.dealname) {
    throw new Error('Missing required field: properties.dealname');
  }
  if (payload.properties.amount === undefined || payload.properties.amount === null) {
    throw new Error('Missing required field: properties.amount');
  }
  if (!payload.properties.associatedcompanyid) {
    throw new Error('Missing required field: properties.associatedcompanyid');
  }

  const { dealname, amount, associatedcompanyid } = payload.properties;

  let domain: string;
  if (payload.properties.domain) {
    domain = payload.properties.domain;
  } else if (config.resolveCompanyDomain) {
    domain = await config.resolveCompanyDomain(associatedcompanyid);
  } else {
    const hubspotBaseUrl = config.hubspotBaseUrl || 'https://api.hubapi.com';
    const companyUrl = `${hubspotBaseUrl}/crm/v3/objects/companies/${associatedcompanyid}`;
    const response = await config.fetch(companyUrl, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${config.hubspotAccessToken}`,
        'Content-Type': 'application/json',
      },
    });
    if (!response.ok) {
      throw new Error(`Failed to fetch company from HubSpot: ${response.status} ${response.statusText} at ${companyUrl}`);
    }
    const companyData = await response.json() as { domain?: string };
    if (!companyData.domain) {
      throw new Error(`Company ${associatedcompanyid} does not have a domain property`);
    }
    domain = companyData.domain;
  }

  const salesforceUrl = `${config.salesforceInstanceUrl}/services/data/v68.0/sobjects/Account/Domain/${encodeURIComponent(domain)}`;
  const body = {
    attributes: { type: 'Account' },
    Name: dealname,
    Website: domain,
    AnnualRevenue: amount,
  };

  const response = await config.fetch(salesforceUrl, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${config.salesforceAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (response.status === 300) {
    throw new Error(`Multiple Accounts found for domain ${domain} (300 Multiple Choices)`);
  }
  if (!response.ok && response.status !== 204) {
    throw new Error(`Salesforce upsert failed: ${response.status} ${response.statusText} at ${salesforceUrl}`);
  }

  if (response.status === 204) {
    return {
      id: '',
      success: true,
      errors: [],
      created: false,
    };
  }

  const result = await response.json() as UpsertResult;
  return result;
}

