import { handle, HubSpotDealWebhookPayload, ConnectorConfig } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      fetch,
      salesforceInstanceUrl: 'https://test.salesforce.com',
      salesforceAccessToken: 'test-sf-token',
      hubspotAccessToken: 'test-hs-token',
      resolveCompanyDomain: async (companyId: number) => {
        if (companyId === 67890) return 'acme.com';
        throw new Error(`Unknown company ${companyId}`);
      },
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.id).toBe('001xx000003DGhpAAG');
    expect(result.created).toBe(false);
  });
});

