    await expect(handle({
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, amount: undefined as any },
    }, baseConfig)).rejects.toThrow('Missing required field: properties.amount');

    await expect(handle({
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, associatedcompanyid: undefined as any },
    }, baseConfig)).rejects.toThrow('Missing required field: properties.associatedcompanyid');
  });

  it('fetches company domain from HubSpot and upserts Account', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/companies/67890')) {
        return jsonResponse({ domain: 'acme.com' });
      }
      if (req.url.includes('/services/data/v68.0/sobjects/Account/Domain/acme.com')) {
        return jsonResponse({ id: '001xx000003DGhpAAG', success: true, errors: [], created: true });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

